/** Source: title_screen.c → SpriteCB_PokemonLogoShine */
export const SpriteCB_PokemonLogoShine: SpriteCallback = (sprite, rt) => {
  if (sprite.x < DISPLAY_WIDTH + 32)
      {
           
           
          if (sprite.data[0] != SHINE_MODE_SINGLE_NO_BG_COLOR)
          {
              let backgroundColor = 0;

              if (sprite.x < DISPLAY_WIDTH / 2)
              {
                   
                  if (sprite.data[1] < 31)
                      sprite.data[1]++;
                  if (sprite.data[1] < 31)
                      sprite.data[1]++;
              }
              else
              {
                   
                  if (sprite.data[1] != 0)
                      sprite.data[1]--;
                  if (sprite.data[1] != 0)
                      sprite.data[1]--;
              }

              backgroundColor = RGB(sprite.data[1], sprite.data[1], sprite.data[1]);

               
               
              if (sprite.x == DISPLAY_WIDTH / 2 + (3 * SHINE_SPEED)
               || sprite.x == DISPLAY_WIDTH / 2 + (4 * SHINE_SPEED)
               || sprite.x == DISPLAY_WIDTH / 2 + (5 * SHINE_SPEED)
               || sprite.x == DISPLAY_WIDTH / 2 + (6 * SHINE_SPEED))
                  rt.gPlttBufferFaded.set(0, RGB(24, 31, 12));
              else
                  rt.gPlttBufferFaded.set(0, backgroundColor);
          }

          sprite.x += SHINE_SPEED;
      }
      else
      {
           
          rt.gPlttBufferFaded.set(0, RGB_BLACK);
          DestroySprite(rt, sprite.spriteId);
      }
};

