/** Source: title_screen.c → Task_TitleScreenPhase1 */
export const Task_TitleScreenPhase1: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (JOY_NEW(A_B_START_SELECT) || task.data[1])
      {
          task.data[1] = true;
          task.data[0] = 0;
      }

      if (task.data[0] != 0)
      {
          let frameNum = task.data[0];
          if (frameNum == 176)
              StartPokemonLogoShine(SHINE_MODE_DOUBLE);
          else if (frameNum == 64)
              StartPokemonLogoShine(SHINE_MODE_SINGLE);

          task.data[0]--;
      }
      else
      {
          let spriteId = 0;

          // MANUAL FIX session 81 : 1:1 décomp title_screen.c:709 — DISPCNT
          // = BG2+OBJ uniquement. Le transpileur a expansé en BG0+BG1+BG2+BG3
          // par erreur → Rayquaza (BG0) + Clouds (BG1) visibles trop tôt
          // pendant la descente du banner Émeraude (= devrait être BG noir).
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG2_ON | DISPCNT_OBJ_ON);
          rt.SetGpuReg(REG_OFFSET_WININ, 0);
          rt.SetGpuReg(REG_OFFSET_WINOUT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_OBJ | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_ALL);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 0));
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);

           
          spriteId = CreateSprite(rt, sVersionBannerLeftSpriteTemplate, VERSION_BANNER_LEFT_X, VERSION_BANNER_Y, 0);
          _gs(rt, spriteId).data[0] = ((gTitleScreenAlphaBlend)?.length ?? 0);
          _gs(rt, spriteId).data[1] = taskId;

           
          spriteId = CreateSprite(rt, sVersionBannerRightSpriteTemplate, VERSION_BANNER_RIGHT_X, VERSION_BANNER_Y, 0);
          _gs(rt, spriteId).data[1] = taskId;

          task.data[0] = 144;
          task.func = (t) => Task_TitleScreenPhase2(t, rt);
      }
};

/** Source: title_screen.c → Task_TitleScreenPhase2 */
export const Task_TitleScreenPhase2: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let yPos = 0;
       
      if (JOY_NEW(A_B_START_SELECT) || task.data[1])
      {
          task.data[1] = true;
          task.data[0] = 0;
      }

      if (task.data[0] != 0)
      {
          task.data[0]--;
      }
      else
      {
          task.data[1] = true;
          rt.SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG0 | BLDCNT_TGT2_BD);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(6, 15));
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1
                                      | DISPCNT_OBJ_1D_MAP
                                      | DISPCNT_BG0_ON
                                      | DISPCNT_BG1_ON
                                      | DISPCNT_BG2_ON
                                      | DISPCNT_OBJ_ON);
          CreatePressStartBanner(rt, START_BANNER_X, 108);
          CreateCopyrightBanner(rt, START_BANNER_X, 148);
          task.data[4] = 0;
          task.func = (t) => Task_TitleScreenPhase3(t, rt);
      }

      if (!(task.data[0] & 3) && task.data[2] != 0)
          task.data[2]++;
      if (!(task.data[0] & 1) && task.data[3] != 0)
          task.data[3]++;

      // Décomp : `u32 yPos` → multiplie en unsigned 32-bit. Pour data[3]=-32 → yPos
      // = 0xFFFFE000 (cast u32). yPos/0x10000 (unsigned) = 0xFFFF (= sign-extend
      // pour BG2Y_H 12-bit signed). En TS on force unsigned via `>>> 0`.
      yPos = (task.data[3] * 256) >>> 0;
      rt.SetGpuReg(REG_OFFSET_BG2Y_L, yPos & 0xFFFF);
      rt.SetGpuReg(REG_OFFSET_BG2Y_H, (yPos >>> 16) & 0xFFFF);

      task.data[5] = 15;  
      task.data[6] = 6;
};

/** Source: title_screen.c → Task_TitleScreenPhase3 */
export const Task_TitleScreenPhase3: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const newKeys = rt.gMain.newKeys;
  if ((JOY_NEW(A_BUTTON)) || (JOY_NEW(START_BUTTON)))
      {
          FadeOutBGM(4);
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_WHITEALPHA");
          rt.SetMainCallback2(CB2_GoToMainMenu);
      }
      else if (JOY_HELD(CLEAR_SAVE_BUTTON_COMBO) == CLEAR_SAVE_BUTTON_COMBO)
      {
          rt.SetMainCallback2(CB2_GoToClearSaveDataScreen);
      }
      else if (JOY_HELD(RESET_RTC_BUTTON_COMBO) == RESET_RTC_BUTTON_COMBO
        && CanResetRTC() == true)
      {
          FadeOutBGM(4);
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_BLACK");
          rt.SetMainCallback2(CB2_GoToResetRtcScreen);
      }
      else if (JOY_HELD(BERRY_UPDATE_BUTTON_COMBO) == BERRY_UPDATE_BUTTON_COMBO)
      {
          FadeOutBGM(4);
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_BLACK");
          rt.SetMainCallback2(CB2_GoToBerryFixScreen);
      }
      else
      {
          rt.SetGpuReg(REG_OFFSET_BG2Y_L, 0);
          rt.SetGpuReg(REG_OFFSET_BG2Y_H, 0);
          if (++task.data[0] & 1)
          {
              task.data[4]++;(globalThis as any).gBattle_BG1_Y = Math.trunc(task.data[4] / 2);
              (globalThis as any).gBattle_BG1_X = 0;
          }
          UpdateLegendaryMarkingColor(task.data[0]);
          if ((gMPlayInfo_BGM.status & 0xFFFF) == 0)
          {
              // 1:1 décomp title_screen.c:818-822 demo loop. La task n'est pas
              // détruite : runtime n'appelle plus runTasks() pendant les CB2 de
              // transition (= seuls les MainCB2* le font), donc Phase3 ne
              // retrigger pas après le SetMainCallback2 (= match exact décomp).
              rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_WHITEALPHA");
              rt.SetMainCallback2(CB2_GoToCopyrightScreen);
          }
      }
};

