/** Source: title_screen.c → CB2_InitTitleScreen */
export const CB2_InitTitleScreen: CB2Callback = (rt) => {
  switch (gMain.state)
      {
      default:
      case 0:
          rt.SetVBlankCallback(VBlankCB);
          rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          /* deref-write skipped: (PLTT) = */ void 0 ;// RGB_WHITE;
          rt.SetGpuReg(REG_OFFSET_DISPCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BG2CNT, 0);
          rt.SetGpuReg(REG_OFFSET_BG1CNT, 0);
          rt.SetGpuReg(REG_OFFSET_BG0CNT, 0);
          rt.SetGpuReg(REG_OFFSET_BG2HOFS, 0);
          rt.SetGpuReg(REG_OFFSET_BG2VOFS, 0);
          rt.SetGpuReg(REG_OFFSET_BG1HOFS, 0);
          rt.SetGpuReg(REG_OFFSET_BG1VOFS, 0);
          rt.SetGpuReg(REG_OFFSET_BG0HOFS, 0);
          rt.SetGpuReg(REG_OFFSET_BG0VOFS, 0);
          DmaFill16(3, 0, VRAM, VRAM_SIZE);
          DmaFill32(3, 0, OAM, OAM_SIZE);
          DmaFill16(3, 0, (PLTT + 2), PLTT_SIZE - 2);
          ResetPaletteFade();
          gMain.state = 1;
          break;
      case 1:
           
          LZ77UnCompVram(gTitleScreenPokemonLogoGfx, (BG_CHAR_ADDR(0)));
          LZ77UnCompVram(gTitleScreenPokemonLogoTilemap, (BG_SCREEN_ADDR(9)));
          LoadPalette(gTitleScreenBgPalettes, BG_PLTT_ID(0), 15 * PLTT_SIZE_4BPP);
           
          LZ77UnCompVram(sTitleScreenRayquazaGfx, (BG_CHAR_ADDR(2)));
          LZ77UnCompVram(sTitleScreenRayquazaTilemap, (BG_SCREEN_ADDR(26)));
           
          LZ77UnCompVram(sTitleScreenCloudsGfx, (BG_CHAR_ADDR(3)));
          LZ77UnCompVram(gTitleScreenCloudsTilemap, (BG_SCREEN_ADDR(27)));
          ScanlineEffect_Stop();
          ResetTasks();
          ResetSpriteData(rt);
          FreeAllSpritePalettes();
          (globalThis as any).gReservedSpritePaletteCount = 9;
          LoadCompressedSpriteSheet(sSpriteSheet_EmeraldVersion);
          LoadCompressedSpriteSheet(sSpriteSheet_PressStart);
          LoadCompressedSpriteSheet(sPokemonLogoShineSpriteSheet);
          LoadPalette(gTitleScreenEmeraldVersionPal, OBJ_PLTT_ID(0), PLTT_SIZE_4BPP);
          LoadSpritePalette(sSpritePalette_PressStart[0]);
          gMain.state = 2;
          break;
      case 2:
      {
          let taskId = rt.CreateTask((t) => Task_TitleScreenPhase1(t, rt), 0);
          const task = rt.gTasks.get(taskId)!;
          task.data[0] = 256;
          task.data[1] = 0;
          task.data[2] = -16;
          task.data[3] = -32;
          gMain.state = 3;
          break;
      }
      case 3:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 1, 16, 0, "RGB_WHITEALPHA");
          rt.SetVBlankCallback(VBlankCB);
          gMain.state = 4;
          break;
      case 4:
          PanFadeAndZoomScreen(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, 0x100, 0);
          rt.SetGpuReg(REG_OFFSET_BG2X_L, -29 * 256);
          rt.SetGpuReg(REG_OFFSET_BG2X_H, -1);
          rt.SetGpuReg(REG_OFFSET_BG2Y_L, -32 * 256);
          rt.SetGpuReg(REG_OFFSET_BG2Y_H, -1);
          rt.SetGpuReg(REG_OFFSET_WIN0H, 0);
          rt.SetGpuReg(REG_OFFSET_WIN0V, 0);
          rt.SetGpuReg(REG_OFFSET_WIN1H, 0);
          rt.SetGpuReg(REG_OFFSET_WIN1V, 0);
          rt.SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN1_BG_ALL | WININ_WIN1_OBJ);
          rt.SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WINOBJ_ALL);
          rt.SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG2 | BLDCNT_EFFECT_LIGHTEN);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 12);
          rt.SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(3) | BGCNT_CHARBASE(2) | BGCNT_SCREENBASE(26) | BGCNT_16COLOR | BGCNT_TXT256x256);
          rt.SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(2) | BGCNT_CHARBASE(3) | BGCNT_SCREENBASE(27) | BGCNT_16COLOR | BGCNT_TXT256x256);
          rt.SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(1) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(9) | BGCNT_256COLOR | BGCNT_AFF256x256);
          EnableInterrupts(INTR_FLAG_VBLANK);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1
                                      | DISPCNT_OBJ_1D_MAP
                                      | DISPCNT_BG2_ON
                                      | DISPCNT_OBJ_ON
                                      | DISPCNT_WIN0_ON
                                      | DISPCNT_OBJWIN_ON);
          m4aSongNumStart(MUS_TITLE);
          gMain.state = 5;
          break;
      case 5:
          if (!UpdatePaletteFade())
          {
              StartPokemonLogoShine(SHINE_MODE_SINGLE_NO_BG_COLOR);
              ScanlineEffect_InitWave(0, DISPLAY_HEIGHT, 4, 4, 0, SCANLINE_EFFECT_REG_BG1HOFS, true);
              rt.SetMainCallback2(MainCB2);
          }
          break;
      }
};

